from fastapi import FastAPI, Depends, Security
from fastapi.security import OAuth2PasswordBearer
from fastapi.openapi.utils import get_openapi

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

def dep_without_scopes():
    return Security(oauth2_scheme)

def dep_with_scopes():
    return Security(oauth2_scheme, scopes=["scope1"])

@app.get("/without")
def read_without(dep = Depends(dep_without_scopes)):
    return {"message": "without"}

@app.get("/with")
def read_with(dep = Depends(dep_with_scopes)):
    return {"message": "with"}

# The issue is about how dependencies are handled.
# Let's see what the OpenAPI schema looks like.
openapi_schema = get_openapi(app, app.openapi_url)
import json
print(json.dumps(openapi_schema, indent=2))

